insert into sse.agent values ('A00', 'Törzskoordinátor', 'FELADAT: A törzsfőnök munkáját segíted: tervezési időterv, törzsritmus, feladatkiosztás, készenléti követés,
insert into sse.agent values ('A01', 'S-1 személyügy', 'FELADAT: Erőhelyzet, veszteségbecslés, pótlás, személyügyi helyzetértékelés.
insert into sse.agent values ('A02', 'S-2 felderítés', 'FELADAT: IPOE vezetése, ellenséges COA-k, PIR-javaslat, gyűjtési hiányok.
insert into sse.agent values ('A03', 'S-3 műveletek, vezető tervező', 'FELADAT: A szakagi hozzájárulások integrálása; küldetéselemzés, COA, szinkronizáció, döntési mátrix, parancs.
insert into sse.agent values ('A04', 'S-4 logisztika', 'FELADAT: Fenntartási számvetés, ellátás, szállítás, technikai biztosítás.
insert into sse.agent values ('A05', 'S-6 híradás', 'FELADAT: Híradó és informatikai koncepció, PACE terv, hálózati kockázatok.
